import { createHmac } from "node:crypto";

// TELEMETRY-01: every write to onzio.record_page_event is signed. The anon key
// is public, so without this anyone could post forged events straight to
// PostgREST. The key lives in onzio_private.telemetry_ingest_keys (generated by
// the migration, read once by an operator) and in Vercel as
// TELEMETRY_INGEST_SECRET, as 64 lowercase hex characters (the 32 key bytes).

export const INGEST_SECRET_ENV = "TELEMETRY_INGEST_SECRET";

const SECRET_HEX = /^[0-9a-f]{64}$/;

/** The signing key as hex, or null unless it is exactly 64 lowercase hex characters. */
export function ingestSecret(env: Record<string, string | undefined> = process.env): string | null {
  const value = env[INGEST_SECRET_ENV];
  return value !== undefined && SECRET_HEX.test(value) ? value : null;
}

/**
 * HMAC-SHA256 over `clubId + "\n" + payloadText`, as lowercase hex. The database
 * recomputes this over the same text, so sign the exact string that is sent
 * (never a re-serialised object).
 */
export function signPayload(clubId: string, payloadText: string, secretHex: string): string {
  if (!SECRET_HEX.test(secretHex)) throw new Error("Telemetry ingest secret must be 64 lowercase hex characters.");
  return createHmac("sha256", Buffer.from(secretHex, "hex")).update(`${clubId}\n${payloadText}`, "utf8").digest("hex");
}
